                                                                     std::vector<CGAL::Triangle_3<CGAL::Simple_cartesian<double> >::const_iterator>>>::Intersecting_iterators iterators =
        tree.intersecting_objects(CGAL::AABB_box(b.min(), b.max()));

    for (; iterators != tree.intersecting_objects_end(); ++iterators) {
        const CGAL::Triangle_3<CGAL::Simple_cartesian<double>>& triangle = *iterators->first.primitive();
        if (b.isInside(triangle[0]) && b.isInside(triangle[1]) && b.isInside(triangle[2])) {
            count++;
        }
    }
    return count;
